<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/read-model.php';require_once __DIR__.'/media-store.php';
try{kalite_filo_admin_require_method('PATCH');kalite_filo_admin_require_same_origin();kalite_filo_admin_start_session();kalite_filo_admin_require_authentication();kalite_filo_admin_require_csrf();kalite_filo_admin_require_roles(['owner','admin','editor']);$body=kalite_filo_admin_read_json();$id=(string)($body['id']??'');$lock=kalite_filo_admin_lock_media_store();try{$records=kalite_filo_admin_media_records();$updated=null;foreach($records as &$record)if(($record['id']??'')===$id){$updated=kalite_filo_admin_normalize_media_metadata($body,$record);$record=$updated;break;}unset($record);if(!is_array($updated))kalite_filo_admin_json(['error'=>'not_found'],404);kalite_filo_admin_write_media_records($records);}finally{kalite_filo_admin_unlock_media_store($lock);}kalite_filo_admin_audit('media_update','success',['id'=>$id]);kalite_filo_admin_json(['media'=>$updated]);}catch(InvalidArgumentException $e){kalite_filo_admin_json(['error'=>$e->getMessage()],422);}catch(Throwable $e){error_log('Media update failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
